-- Lot 203 : payloads 61 a 90 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-095","moteur":"chatgpt","payload":"[RaccourcIA — /instructionvisual]\n\nMISSION\nTransformer une action en étapes illustrées. Associe un geste par vignette à un verbe court, avec pictogrammes consistants. Pour une opération sensible, pars de la procédure officielle fournie.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel contenu exact dois-je intégrer pour « etapes » ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Notice visuelle » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Associe un geste par vignette à un verbe court, avec pictogrammes consistants. Pour une opération sensible, pars de la procédure officielle fournie. Le format par défaut est 16:9 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve l’enveloppe, les proportions, l’orientation et les repères vérifiés du sujet; distingue clairement représentation réelle et conceptuelle.\n\nÉVITER\nÉvite composants inventés présentés comme réels, cotes déduites sans échelle, légendes illisibles, perspective impossible et fausse précision. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"d9240892abe3e0c07969c67007a9f7446b71878e0b2e7105cbc3d6b1f2bdf091"},{"ref":"RCI-IMG-095","moteur":"claude","payload":"[RaccourcIA — /instructionvisual]\n\nMISSION\nTransformer une action en étapes illustrées. Associe un geste par vignette à un verbe court, avec pictogrammes consistants. Pour une opération sensible, pars de la procédure officielle fournie.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel contenu exact dois-je intégrer pour « etapes » ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Notice visuelle » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Associe un geste par vignette à un verbe court, avec pictogrammes consistants. Pour une opération sensible, pars de la procédure officielle fournie. Le format par défaut est 16:9 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve l’enveloppe, les proportions, l’orientation et les repères vérifiés du sujet; distingue clairement représentation réelle et conceptuelle.\n\nÉVITER\nÉvite composants inventés présentés comme réels, cotes déduites sans échelle, légendes illisibles, perspective impossible et fausse précision. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"e6fed5a625ce76eb065f901e8f774bd93ae84978aee7425fb48130994f8b460e"},{"ref":"RCI-IMG-095","moteur":"gemini","payload":"[RaccourcIA — /instructionvisual]\n\nMISSION\nTransformer une action en étapes illustrées. Associe un geste par vignette à un verbe court, avec pictogrammes consistants. Pour une opération sensible, pars de la procédure officielle fournie.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une 